starter_code:
twoFer: function [name][
    panic "Please implement the twoFer function"
]

example_solution:
twoFer: function [
    name
][
    switch name=""  -> twoFer "you"
                    -> "One for " ++ name ++ ", one for me."
]

test_code:
import.version:3.0.0 {unitt}! 
import {src/two-fer}!

describe "Two Fer" [
    it "no name given" [
        expects.be:'equal? @[
            "One for you, one for me."
            twoFer ""
        ]
    ]

    it.skip "a name given" [
        expects.be:'equal? @[
            "One for Alice, one for me."
            twoFer "Alice"
        ]
    ]

    it.skip "another name given" [
        expects.be:'equal? @[
            "One for Bob, one for me."
            twoFer "Bob"
        ]
    ]
]
